import { Component, Prop, h } from "@stencil/core";

/**
 * @since 0.0.10
 * @status deprecated
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-menu-divider",
	styleUrl: "menu-divider.scss",
	shadow: true,
})
export class MenuDivider {
	/** Toggle css class - Align the divider vertically. */
	@Prop({ reflect: true }) vertical = false;

	render() {
		return (
			<div
				part="base"
				class={{
					"menu-divider": true,
					"menu-divider--vertical": this.vertical,
				}}
				// biome-ignore lint/a11y/useAriaPropsForRole: W3C does not recommend using role="separator" for menu dividers
				role="separator"
				aria-hidden="true"
			/>
		);
	}
}
